FIRST_SIGNAL_DATE = min(FROZEN_SIGNALS.keys())


def initialize(context):
    set_benchmark('000300.XSHG')
    set_option('use_real_price', True)
    set_option('avoid_future_data', True)
    set_order_cost(
        OrderCost(open_commission=0.0003, close_commission=0.0003, min_commission=5),
        type='stock',
    )

    g.strategy_id = 'v56_dividend_low_vol_fcf_shadow_basket'
    g.script_version = 'v56_basket_frozen_signals_20260718'
    g.target_exposure = 0.995
    g.selection_count = 30
    g.lot_size = 100
    g.executed_dates = set()
    g.debug = True

    log.info('V5.6 basket script=%s frozen_signal_dates=%d first_signal=%s benchmark=000300.XSHG' % (g.script_version, len(FROZEN_SIGNALS), FIRST_SIGNAL_DATE))
    log.info('V5.6 frozen rule: bank + utilities/electricity + highway + port/rail; no recompute, no tuning, no accepted-strategy claim.')
    log.info('V5.6 benchmark note: JoinQuant 000300.XSHG is display-only; formal comparison uses local same-pool total-return benchmark.')

    run_daily(maybe_rebalance, time='09:40')
    run_daily(after_close_log, time='after_close')


def maybe_rebalance(context):
    today = context.current_dt.date().isoformat()
    if today not in FROZEN_SIGNALS:
        return
    if today in g.executed_dates:
        return

    rows = FROZEN_SIGNALS[today]
    tradable_rows = []
    for code, weight, sector_id in rows:
        if is_tradable(code):
            tradable_rows.append((code, weight, sector_id))
        else:
            log.info('V5.6 skip untradable date=%s code=%s sector=%s' % (today, code, sector_id))

    if not tradable_rows:
        log.info('V5.6 BLOCKED no tradable selected stocks date=%s' % today)
        g.executed_dates.add(today)
        return

    current_total = context.portfolio.total_value
    log.info(
        'V5.6 rebalance date=%s raw_selected=%d tradable_selected=%d target_exposure=%.4f selected=%s'
        % (today, len(rows), len(tradable_rows), g.target_exposure, ','.join([item[0] for item in tradable_rows]))
    )

    execute_target_weights(context, tradable_rows, current_total)
    g.executed_dates.add(today)


def execute_target_weights(context, target_rows, total_value):
    selected = set([code for code, _weight, _sector in target_rows])
    current_positions = list(context.portfolio.positions.keys())
    current_data = get_current_data()

    for code in current_positions:
        if code not in selected:
            try:
                order_target_value(code, 0)
            except Exception as exc:
                log.info('V5.6 sell failed code=%s error=%s' % (code, str(exc)))

    for code, weight, sector_id in target_rows:
        target_value = total_value * float(weight) * g.target_exposure
        estimated_price = get_estimated_trade_price(current_data, code)
        if estimated_price is not None:
            min_lot_value = estimated_price * g.lot_size
            if target_value < min_lot_value:
                log.info(
                    'V5.6 capital warning code=%s target_value=%.2f one_lot_value=%.2f price=%.3f lot_size=%d; order may be rejected by lot-size rule.'
                    % (code, target_value, min_lot_value, estimated_price, g.lot_size)
                )
        try:
            order_target_value(code, target_value)
        except Exception as exc:
            log.info('V5.6 buy/adjust failed code=%s sector=%s target_value=%.2f error=%s' % (code, sector_id, target_value, str(exc)))


def get_estimated_trade_price(current_data, code):
    try:
        item = current_data[code]
    except Exception:
        return None
    for attr in ('last_price', 'day_open', 'high_limit', 'low_limit'):
        try:
            value = getattr(item, attr, None)
        except Exception:
            value = None
        if value is not None and value > 0:
            return float(value)
    return None


def is_tradable(code):
    current_data = get_current_data()
    try:
        item = current_data[code]
    except Exception:
        return False
    if getattr(item, 'paused', False):
        return False
    if getattr(item, 'is_st', False):
        return False
    return True


def after_close_log(context):
    today = context.current_dt.date().isoformat()
    if today not in FROZEN_SIGNALS:
        return
    positions = []
    for code, pos in context.portfolio.positions.items():
        if pos.total_amount > 0:
            positions.append('%s:%s' % (code, int(pos.total_amount)))
    log.info(
        'V5.6 after_close date=%s total_value=%.2f cash=%.2f positions=%s'
        % (today, context.portfolio.total_value, context.portfolio.cash, ';'.join(positions))
    )
